 "content": "from collections import Counter


def _runs(values, bg):
    runs = []
    i = 0
    while i < len(values):
        if values[i] == bg:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        if j - i >= 2:
            runs.append((i, j, color))
        i = j
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars = None
    orientation = None

    # The two equal-colored bars sit on opposite horizontal borders.
    top_runs = _runs(grid[0], bg)
    bottom_runs = _runs(grid[-1], bg)
    for a in top_runs:
        for b in bottom_runs:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                bars = (a, b)
                orientation = "horizontal"
                break
        if bars:
            break

    # Or they sit on the opposite vertical borders.
    if bars is None:
        left_runs = _runs([grid[r][0] for r in range(h)], bg)
        right_runs = _runs([grid[r][-1] for r in range(h)], bg)
        for a in left_runs:
            for b in right_runs:
                if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                    bars = (a, b)
                    orientation = "vertical"
                    break
            if bars:
                break

    if bars is None:
        raise ValueError("Could not locate the matching opposite-edge bars")

    out = [row[:] for row in grid]
    bar_cells = set()
    if orientation == "horizontal":
        top, bottom = bars
        for c in range(top[0], top[1]):
            bar_cells.add((0, c))
        for c in range(bottom[0], bottom[1]):
            bar_cells.add((h - 1, c))
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and (r, c) not in bar_cells]
        shift = top[0] - bottom[0]
        for r, c, color in markers:
            for rr in range(1, r):
                out[rr][c] = color
            companion = c - shift
            if 0 <= companion < w:
                for rr in range(h - 1):
                    out[rr][companion] = color
        for r, c, _ in markers:
            out[r][c] = 4
    else:
        left, right = bars
        for r in range(left[0], left[1]):
            bar_cells.add((r, 0))
        for r in range(right[0], right[1]):
            bar_cells.add((r, w - 1))
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and (r, c) not in bar_cells]
        shift = right[0] - left[0]
        for r, c, color in markers:
            for cc in range(1, c):
                out[r][cc] = color
            companion = r + shift
            if 0 <= companion < h:
                for cc in range(w - 1):
                    out[companion][cc] = color
        for r, c, _ in markers:
            out[r][c] = 4
    return out


